package set.starlev.utils.detectors

import set.starlev.StarredHeltix
import set.starlev.utils.CacheManager

/**
 * Детектор текущей локации на основе данных scoreboard.
 * Определяет локацию по символу ⏣/ф и заголовку скорборда.
 */
object LocationDetector {

    private var cachedLocation: String? = null
    private var lastPollTime: Long = 0
    private const val POLL_INTERVAL_MS = 1000L

    /**
     * Получить текущую локацию (кэшируется на 1 секунду).
     * @return Название локации или null если не определена
     */
    fun getCurrentLocation(): String? {
        val now = System.currentTimeMillis()
        if (now - lastPollTime < POLL_INTERVAL_MS) return cachedLocation

        lastPollTime = now
        val location = detectLocation()
        cachedLocation = location
        return location
    }

    /**
     * Получить чистое название локации без цветовых кодов.
     */
    fun getCurrentLocationClean(): String? {
        return getCurrentLocation()?.let { cleanLocationName(it) }
    }

    /**
     * Проверить, находится ли игрок в определённой локации.
     * @param locationName название локации (регистронезависимо)
     */
    fun isInLocation(locationName: String): Boolean {
        val current = getCurrentLocationClean() ?: return false
        return current.contains(locationName, ignoreCase = true)
    }

    /**
     * Проверить, находится ли игрок в одной из перечисленных локаций.
     */
    fun isInAnyLocation(vararg locationNames: String): Boolean {
        val current = getCurrentLocationClean() ?: return false
        return locationNames.any { current.contains(it, ignoreCase = true) }
    }

    private fun detectLocation(): String? {
        // Способ 1: Ищем символ ⏣ в строках scoreboard
        val lines = ScoreboardDetector.getScoreboardText()
        for (line in lines) {
            val idx = line.indexOf('⏣')
            if (idx != -1) {
                val after = line.substring(idx + 1).trim()
                if (after.isNotBlank()) {
                    return CacheManager.dedupString(after)
                }
            }
            // Альтернативный символ ф (для некоторых серверов)
            val idxAlt = line.indexOf('ф')
            if (idxAlt != -1) {
                val after = line.substring(idxAlt + 1).trim()
                if (after.isNotBlank()) {
                    return CacheManager.dedupString(after)
                }
            }
        }

        // Способ 2: Проверяем заголовок scoreboard
        val title = ScoreboardDetector.getScoreboardTitle()
        if (title.isNotBlank() && !title.equals("www.hypixel.net", ignoreCase = true)) {
            return CacheManager.dedupString(title)
        }

        return null
    }

    /**
     * Очистить название локации от лишних символов и привести к стандартному виду.
     */
    private fun cleanLocationName(raw: String): String {
        return raw
            .replace(Regex("(?i)§[0-9a-fk-orlnmxz]"), "")
            .replace("⏣", "")
            .replace("ф", "")
            .replace("~", "")
            .trim()
    }

    /**
     * Сбросить кэш (вызывать при смене мира/сервера).
     */
    fun resetCache() {
        cachedLocation = null
        lastPollTime = 0
    }
}

package set.starlev.config.categories

import com.google.gson.annotations.Expose
import io.github.notenoughupdates.moulconfig.annotations.Accordion
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorBoolean
import io.github.notenoughupdates.moulconfig.annotations.ConfigEditorSlider
import io.github.notenoughupdates.moulconfig.annotations.ConfigOption

class MusicConfig {
    @Expose
    @ConfigOption(name = "Включить музыку по локациям", desc = "Автоматически воспроизводит музыку в зависимости от текущей локации.")
    @Accordion
    var locationMusic = LocationMusicConfig()

    class LocationMusicConfig {
        @Expose
        @ConfigOption(name = "Включить?", desc = "Включает систему музыки по локациям.")
        @ConfigEditorBoolean
        var enabled = false

        @Expose
        @ConfigOption(name = "Громкость", desc = "Общая громкость музыки (0-100%).")
        @ConfigEditorSlider(minValue = 0f, maxValue = 100f, minStep = 1f)
        var volume = 50f

        @Expose
        @ConfigOption(name = "Приоритет над игровой музыкой", desc = "Отключает стандартную музыку Minecraft при воспроизведении музыки мода.")
        @ConfigEditorBoolean
        var overrideGameMusic = true

        // Локации - можно добавлять новые по мере необходимости
        @Expose
        @ConfigOption(name = "Хаб (Hub)", desc = "Музыка для центрального хаба.")
        @Accordion
        var hub = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Остров игрока (Private Island)", desc = "Музыка для личного острова.")
        @Accordion
        var privateIsland = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Парк (The Park)", desc = "Музыка для локации Парк.")
        @Accordion
        var thePark = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Спайдерская берлога (Spider's Den)", desc = "Музыка для Спайдерской берлоги.")
        @Accordion
        var spidersDen = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Край Пустоты (The End)", desc = "Музыка для Края Пустоты.")
        @Accordion
        var theEnd = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Багровые острова (Crimson Isle)", desc = "Музыка для Багровых островов.")
        @Accordion
        var crimsonIsle = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Глубинное убежище (Deep Caverns)", desc = "Музыка для Глубинного убежища.")
        @Accordion
        var deepCaverns = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Шахты (Gold Mine / Coal Mine)", desc = "Музыка для начальных шахт.")
        @Accordion
        var mines = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Деревня (Village)", desc = "Музыка для деревни.")
        @Accordion
        var village = LocationMusicEntryConfig()

        @Expose
        @ConfigOption(name = "Подземелья (Dungeons)", desc = "Музыка для подземелий.")
        @Accordion
        var dungeons = LocationMusicEntryConfig()

        class LocationMusicEntryConfig {
            @Expose
            @ConfigOption(name = "Включить для этой локации", desc = "Воспроизводить музыку в этой локации.")
            @ConfigEditorBoolean
            var enabled = true

            @Expose
            @ConfigOption(name = "Путь к файлу", desc = "Путь к аудиофайлу относительно assets/mods/starredheltix/sounds/")
            var soundPath = ""
        }
    }
}
